// Offline audio mix for a project: background music (generated by
// web/music.js or a user-supplied file), voiceover clips, and click effects,
// with the music ducked under the voice. Rendering offline keeps the preview
// and the exported file sample-identical.

import { clamp } from '/lib/timeline.mjs';
import { planMusic, seeded, voiceSpans } from '/lib/music-plan.mjs';
import { loadMusicFile, scheduleMusic, scheduleMusicFile } from './music.js';

function noiseBuffer(context, seconds = 1) {
  const buffer = context.createBuffer(1, Math.ceil(context.sampleRate * seconds), context.sampleRate);
  const random = seeded(99);
  const data = buffer.getChannelData(0);
  for (let index = 0; index < data.length; index += 1) data[index] = (random() * 2) - 1;
  return buffer;
}

// A mouse click is two mechanical transients about 70 ms apart: a bright
// press and a softer release, each with a short plastic body resonance.
function scheduleClick(context, destination, noise, atS, x = 0.5) {
  const pan = context.createStereoPanner();
  pan.pan.value = clamp((x - 0.5) * 0.8, -0.6, 0.6);
  pan.connect(destination);
  for (const [offset, level, pitch] of [[0, 1, 1], [0.072, 0.55, 1.18]]) {
    const at = atS + offset;
    const tick = context.createBufferSource();
    tick.buffer = noise;
    const high = context.createBiquadFilter();
    high.type = 'highpass';
    high.frequency.value = 1800 * pitch;
    const band = context.createBiquadFilter();
    band.type = 'peaking';
    band.frequency.value = 4200 * pitch;
    band.gain.value = 9;
    band.Q.value = 1.2;
    const tickGain = context.createGain();
    tickGain.gain.setValueAtTime(0.0001, at);
    tickGain.gain.exponentialRampToValueAtTime(0.42 * level, at + 0.0012);
    tickGain.gain.exponentialRampToValueAtTime(0.0001, at + 0.018);
    tick.connect(high).connect(band).connect(tickGain).connect(pan);
    tick.start(at, offset * 3);
    tick.stop(at + 0.03);
    const body = context.createOscillator();
    body.type = 'triangle';
    body.frequency.setValueAtTime(2300 * pitch, at);
    body.frequency.exponentialRampToValueAtTime(900 * pitch, at + 0.02);
    const bodyGain = context.createGain();
    bodyGain.gain.setValueAtTime(0.0001, at);
    bodyGain.gain.exponentialRampToValueAtTime(0.09 * level, at + 0.0015);
    bodyGain.gain.exponentialRampToValueAtTime(0.0001, at + 0.035);
    body.connect(bodyGain).connect(pan);
    body.start(at);
    body.stop(at + 0.045);
  }
}

// Soft keyboard ticks across a typing span, one per keystroke at roughly the
// recorder's typing cadence, with seeded variation so it never sounds looped.
function scheduleTyping(context, destination, noise, startS, endS, x = 0.5, seed = 1) {
  const random = seeded(seed);
  const pan = context.createStereoPanner();
  pan.pan.value = clamp((x - 0.5) * 0.6, -0.5, 0.5);
  pan.connect(destination);
  for (let at = startS + 0.02; at < endS; at += 0.06 + (random() * 0.035)) {
    const key = context.createBufferSource();
    key.buffer = noise;
    const band = context.createBiquadFilter();
    band.type = 'bandpass';
    band.frequency.value = 2200 + (random() * 1600);
    band.Q.value = 1.4;
    const gain = context.createGain();
    const level = 0.1 + (random() * 0.07);
    gain.gain.setValueAtTime(0.0001, at);
    gain.gain.exponentialRampToValueAtTime(level, at + 0.002);
    gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.028);
    key.connect(band).connect(gain).connect(pan);
    key.start(at, random() * 0.15);
    key.stop(at + 0.04);
    if (random() < 0.3) {
      const thock = context.createOscillator();
      thock.frequency.setValueAtTime(260 + (random() * 80), at);
      const thockGain = context.createGain();
      thockGain.gain.setValueAtTime(0.0001, at);
      thockGain.gain.exponentialRampToValueAtTime(0.035, at + 0.003);
      thockGain.gain.exponentialRampToValueAtTime(0.0001, at + 0.03);
      thock.connect(thockGain).connect(pan);
      thock.start(at);
      thock.stop(at + 0.04);
    }
  }
}

export async function renderMix(project, { sampleRate = 48000 } = {}) {
  const durationS = project.timeline.outDurationMs / 1000;
  const context = new OfflineAudioContext({ numberOfChannels: 2, length: Math.ceil(durationS * sampleRate), sampleRate });
  const limiter = context.createDynamicsCompressor();
  limiter.threshold.value = -6;
  limiter.knee.value = 4;
  limiter.ratio.value = 12;
  limiter.attack.value = 0.003;
  limiter.release.value = 0.25;
  limiter.connect(context.destination);

  const voiceClips = await Promise.all((project.voice || []).filter((line) => line.src).map(async (line) => {
    const bytes = await fetch(line.src).then((response) => {
      if (!response.ok) throw new Error(`Voice clip ${line.src} returned ${response.status}.`);
      return response.arrayBuffer();
    });
    return { ...line, buffer: await context.decodeAudioData(bytes) };
  }));

  const voiceBus = context.createGain();
  voiceBus.gain.value = 1;
  const rumble = context.createBiquadFilter();
  rumble.type = 'highpass';
  rumble.frequency.value = 90;
  const presence = context.createBiquadFilter();
  presence.type = 'peaking';
  presence.frequency.value = 3200;
  presence.gain.value = 2.5;
  voiceBus.connect(rumble).connect(presence).connect(limiter);
  for (const clip of voiceClips) {
    const source = context.createBufferSource();
    source.buffer = clip.buffer;
    source.connect(voiceBus);
    source.start(clip.outMs / 1000);
  }

  if (project.music) {
    // The arrangement (generated) or the fades (file) shape the music; the bus
    // only sets the level, ducks under narration, and guards the last samples.
    const plan = planMusic(project);
    const musicBus = context.createGain();
    musicBus.gain.setValueAtTime(plan.volume, 0);
    musicBus.gain.setValueAtTime(plan.volume, Math.max(0, durationS - 0.12));
    musicBus.gain.linearRampToValueAtTime(0, durationS);
    musicBus.connect(limiter);
    const duck = context.createGain();
    duck.connect(musicBus);
    const ducked = 10 ** ((project.audio?.duckingDb ?? -10) / 20);
    duck.gain.setValueAtTime(1, 0);
    for (const [start, end] of voiceSpans(project)) {
      duck.gain.setTargetAtTime(ducked, Math.max(0, start - 0.25), 0.08);
      duck.gain.setTargetAtTime(1, end + 0.15, 0.3);
    }
    if (plan.kind === 'file') scheduleMusicFile(context, duck, plan, await loadMusicFile(context, plan));
    else scheduleMusic(context, duck, plan);
  }

  if (project.audio?.clickSound !== false && project.sfx?.length) {
    const noise = noiseBuffer(context, 0.5);
    const sfxBus = context.createGain();
    sfxBus.gain.value = 0.9;
    sfxBus.connect(limiter);
    project.sfx.forEach((effect, index) => {
      if (effect.kind === 'typing') {
        if (project.audio?.typingSound !== false) scheduleTyping(context, sfxBus, noise, effect.outMs / 1000, effect.outEndMs / 1000, effect.x, index + 1);
      } else {
        scheduleClick(context, sfxBus, noise, effect.outMs / 1000, effect.x);
      }
    });
  }

  return context.startRendering();
}
